import{_ as t,a0 as l,w as o,s as c,ao as d,I as p,x as a,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Linux 上安全傳輸文件的 14 SCP 命令示例 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上安全傳輸文件的 14 SCP 命令示例 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上安全傳輸文件的 14 SCP 命令示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上安全傳輸文件的 14 SCP 命令示例 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191020 14 SCP Command Examples to Securely Transfer Files in Linux","title":"在 Linux 上安全傳輸文件的 14 SCP 命令示例","tag":"201912","desc":""},"relativePath":"201912/20191020 14 SCP Command Examples to Securely Transfer Files in Linux.md","filePath":"[post].md"}'),h={name:"201912/20191020 14 SCP Command Examples to Securely Transfer Files in Linux.md"};function r(u,s,g,k,b,x){const i=l("Link");return o(),c("div",null,[s[15]||(s[15]=d(`<h1 id="在-linux-上安全傳輸文件的-14-scp-命令示例" tabindex="-1">在 Linux 上安全傳輸文件的 14 SCP 命令示例 <a class="header-anchor" href="#在-linux-上安全傳輸文件的-14-scp-命令示例" aria-label="Permalink to “在 Linux 上安全傳輸文件的 14 SCP 命令示例”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201912/13/100239f31is1ios31vvoo3.jpg" alt=""></p><p>SCP（<ruby>安全複製<rt>Secure Copy</rt></ruby>）是 Linux 和 Unix 之類的系統中的命令列工具，用於通過網絡安全地跨系統傳輸文件和目錄。當我們使用 <code>scp</code> 命令將文件和目錄從本地系統複製到遠程系統時，則在後端與遠程系統建立了 ssh 連接。換句話説，我們可以説 <code>scp</code> 在後端使用了相同的 SSH 安全機制，它需要密碼或密鑰進行身份驗證。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/scp-command-examples-linux.jpg" alt="scp-command-examples-linux"></p><p>在本教程中，我們將討論 14 個有用的 Linux <code>scp</code> 命令示例。</p><p><code>scp</code> 命令語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># scp &lt;選項&gt; &lt;文件或目錄&gt; 用户名@目標主機:/&lt;文件夾&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># scp &lt;選項&gt; 用户名@目標主機:/文件 &lt;本地文件夾&gt;</span></span></code></pre></div><p><code>scp</code> 命令的第一個語法演示瞭如何將文件或目錄從本地系統複製到特定文件夾下的目標主機。</p><p><code>scp</code> 命令的第二種語法演示瞭如何將目標主機中的文件複製到本地系統中。</p><p>下面列出了 <code>scp</code> 命令中使用最廣泛的一些選項，</p><ul><li><code>-C</code> 啓用壓縮</li><li><code>-i</code> 指定識別文件或私鑰</li><li><code>-l</code> 複製時限制帶寬</li><li><code>-P</code> 指定目標主機的 ssh 端口號</li><li><code>-p</code> 複製時保留文件的權限、模式和訪問時間</li><li><code>-q</code> 禁止 SSH 警告消息</li><li><code>-r</code> 遞歸複製文件和目錄</li><li><code>-v</code> 詳細輸出</li></ul><p>現在讓我們跳入示例！</p><h3 id="示例-1-使用-scp-將文件從本地系統複製到遠程系統" tabindex="-1">示例：1）使用 scp 將文件從本地系統複製到遠程系統 <a class="header-anchor" href="#示例-1-使用-scp-將文件從本地系統複製到遠程系統" aria-label="Permalink to “示例：1）使用 scp 將文件從本地系統複製到遠程系統”">​</a></h3><p>假設我們要使用 <code>scp</code> 命令將 jdk 的 rpm 軟件包從本地 Linux 系統複製到遠程系統（172.20.10.8），請使用以下命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp jdk-linux-x64_bin.rpm root@linuxtechi:/opt</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>jdk-linux-x64_bin.rpm                          100%   10MB  27.1MB/s   00:00</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><p>上面的命令會將 jdk 的 rpm 軟件包文件複製到 <code>/opt</code> 文件夾下的遠程系統。</p><h3 id="示例-2-使用-scp-將文件從遠程系統複製到本地系統" tabindex="-1">示例：2）使用 scp 將文件從遠程系統複製到本地系統 <a class="header-anchor" href="#示例-2-使用-scp-將文件從遠程系統複製到本地系統" aria-label="Permalink to “示例：2）使用 scp 將文件從遠程系統複製到本地系統”">​</a></h3><p>假設我們想將文件從遠程系統複製到本地系統下的 <code>/tmp</code> 文件夾，執行以下 <code>scp</code> 命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp root@linuxtechi:/root/Technical-Doc-RHS.odt /tmp</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>Technical-Doc-RHS.odt                         100% 1109KB  31.8MB/s   00:00</span></span>
<span class="line"><span>[root@linuxtechi ~]$ ls -l /tmp/Technical-Doc-RHS.odt</span></span>
<span class="line"><span>-rwx------. 1 pkumar pkumar 1135521 Oct 19 11:12 /tmp/Technical-Doc-RHS.odt</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><h3 id="示例-3-使用-scp-傳輸文件時的詳細輸出-v" tabindex="-1">示例：3）使用 scp 傳輸文件時的詳細輸出（-v） <a class="header-anchor" href="#示例-3-使用-scp-傳輸文件時的詳細輸出-v" aria-label="Permalink to “示例：3）使用 scp 傳輸文件時的詳細輸出（-v）”">​</a></h3><p>在 <code>scp</code> 命令中，我們可以使用 <code>-v</code> 選項啓用詳細輸出。使用詳細輸出，我們可以輕鬆地發現後台確切發生了什麼。這對於調試連接、認證和配置等問題非常有用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~]$ scp -v jdk-linux-x64_bin.rpm root@linuxtechi:/opt</span></span>
<span class="line"><span>Executing: program /usr/bin/ssh host 172.20.10.8, user root, command scp -v -t /opt</span></span>
<span class="line"><span>OpenSSH_7.8p1, OpenSSL 1.1.1 FIPS  11 Sep 2018</span></span>
<span class="line"><span>debug1: Reading configuration data /etc/ssh/ssh_config</span></span>
<span class="line"><span>debug1: Reading configuration data /etc/ssh/ssh_config.d/05-redhat.conf</span></span>
<span class="line"><span>debug1: Reading configuration data /etc/crypto-policies/back-ends/openssh.config</span></span>
<span class="line"><span>debug1: /etc/ssh/ssh_config.d/05-redhat.conf line 8: Applying options for *</span></span>
<span class="line"><span>debug1: Connecting to 172.20.10.8 [172.20.10.8] port 22.</span></span>
<span class="line"><span>debug1: Connection established.</span></span>
<span class="line"><span>…………</span></span>
<span class="line"><span>debug1: Next authentication method: password</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span></code></pre></div><h3 id="示例-4-將多個文件傳輸到遠程系統" tabindex="-1">示例：4）將多個文件傳輸到遠程系統 <a class="header-anchor" href="#示例-4-將多個文件傳輸到遠程系統" aria-label="Permalink to “示例：4）將多個文件傳輸到遠程系統”">​</a></h3><p>可以使用 <code>scp</code> 命令一次性將多個文件複製/傳輸到遠程系統，在 <code>scp</code> 命令中指定多個文件，並用空格隔開，示例如下所示</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp install.txt index.html jdk-linux-x64_bin.rpm root@linuxtechi:/mnt</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>install.txt                                      100%    0     0.0KB/s   00:00</span></span>
<span class="line"><span>index.html                                       100%   85KB   7.2MB/s   00:00</span></span>
<span class="line"><span>jdk-linux-x64_bin.rpm                            100%   10MB  25.3MB/s   00:00</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><h3 id="示例-5-在兩個遠程主機之間傳輸文件" tabindex="-1">示例：5）在兩個遠程主機之間傳輸文件 <a class="header-anchor" href="#示例-5-在兩個遠程主機之間傳輸文件" aria-label="Permalink to “示例：5）在兩個遠程主機之間傳輸文件”">​</a></h3><p>使用 <code>scp</code> 命令，我們可以在兩個遠程主機之間複製文件和目錄，假設我們有一個可以連接到兩個遠程 Linux 系統的本地 Linux 系統，因此從我的本地 Linux 系統中，我可以使用 <code>scp</code> 命令在這兩個系統之間複製文件，</p><p>命令語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># scp 用户名@遠程主機1:/&lt;要傳輸的文件&gt; 用户名@遠程主機2:/&lt;文件夾&gt;</span></span></code></pre></div><p>示例如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># scp root@linuxtechi:~/backup-Oct.zip root@linuxtechi:/tmp</span></span>
<span class="line"><span># ssh root@linuxtechi &quot;ls -l /tmp/backup-Oct.zip&quot;</span></span>
<span class="line"><span>-rwx------. 1 root root 747438080 Oct 19 12:02 /tmp/backup-Oct.zip</span></span></code></pre></div><h3 id="示例-6-遞歸複製文件和目錄-r" tabindex="-1">示例：6）遞歸複製文件和目錄（-r） <a class="header-anchor" href="#示例-6-遞歸複製文件和目錄-r" aria-label="Permalink to “示例：6）遞歸複製文件和目錄（-r）”">​</a></h3><p>在 <code>scp</code> 命令中使用 <code>-r</code> 選項將整個目錄從一個系統遞歸地複製到另一個系統，示例如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -r Downloads root@linuxtechi:/opt</span></span></code></pre></div><p>使用以下命令驗證 <code>Downloads</code> 文件夾是否已複製到遠程系統，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ ssh root@linuxtechi &quot;ls -ld /opt/Downloads&quot;</span></span>
<span class="line"><span>drwxr-xr-x. 2 root root 75 Oct 19 12:10 /opt/Downloads</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><h3 id="示例-7-通過啓用壓縮來提高傳輸速度-c" tabindex="-1">示例：7）通過啓用壓縮來提高傳輸速度（-C） <a class="header-anchor" href="#示例-7-通過啓用壓縮來提高傳輸速度-c" aria-label="Permalink to “示例：7）通過啓用壓縮來提高傳輸速度（-C）”">​</a></h3><p>在 <code>scp</code> 命令中，我們可以通過使用 <code>-C</code> 選項啓用壓縮來提高傳輸速度，它將自動在源主機上啓用壓縮並在目標主機上解壓縮。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~]$ scp -r -C Downloads root@linuxtechi:/mnt</span></span></code></pre></div><p>在以上示例中，我們正在啓用壓縮的情況下傳輸下載目錄。</p><h3 id="示例-8-複製時限制帶寬-l" tabindex="-1">示例：8）複製時限制帶寬（-l） <a class="header-anchor" href="#示例-8-複製時限制帶寬-l" aria-label="Permalink to “示例：8）複製時限制帶寬（-l）”">​</a></h3><p>在 <code>scp</code> 命令中使用 <code>-l</code> 選項設置複製時對帶寬使用的限制。帶寬以 Kbit/s 為單位指定，示例如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -l 500 jdk-linux-x64_bin.rpm  root@linuxtechi:/var</span></span></code></pre></div><h3 id="示例-9-在-scp-時指定其他-ssh-端口-p" tabindex="-1">示例：9）在 scp 時指定其他 ssh 端口（-P） <a class="header-anchor" href="#示例-9-在-scp-時指定其他-ssh-端口-p" aria-label="Permalink to “示例：9）在 scp 時指定其他 ssh 端口（-P）”">​</a></h3><p>在某些情況下，目標主機上的 ssh 端口會更改，因此在使用 <code>scp</code> 命令時，我們可以使用 <code>-P</code> 選項指定 ssh 端口號。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -P 2022 jdk-linux-x64_bin.rpm  root@linuxtechi:/var</span></span></code></pre></div><p>在上面的示例中，遠程主機的 ssh 端口為 “2022”。</p><h3 id="示例-10-複製時保留文件的權限、模式和訪問時間-p" tabindex="-1">示例：10）複製時保留文件的權限、模式和訪問時間（-p） <a class="header-anchor" href="#示例-10-複製時保留文件的權限、模式和訪問時間-p" aria-label="Permalink to “示例：10）複製時保留文件的權限、模式和訪問時間（-p）”">​</a></h3><p>從源複製到目標時，在 <code>scp</code> 命令中使用 <code>-p</code> 選項保留權限、訪問時間和模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -p jdk-linux-x64_bin.rpm  root@linuxtechi:/var/tmp</span></span>
<span class="line"><span>jdk-linux-x64_bin.rpm                            100%   10MB  13.5MB/s   00:00</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><h3 id="示例-11-在-scp-中以安靜模式傳輸文件-q" tabindex="-1">示例：11）在 scp 中以安靜模式傳輸文件（-q） <a class="header-anchor" href="#示例-11-在-scp-中以安靜模式傳輸文件-q" aria-label="Permalink to “示例：11）在 scp 中以安靜模式傳輸文件（-q）”">​</a></h3><p>在 <code>scp</code> 命令中使用 <code>-q</code> 選項可禁止顯示 ssh 的傳輸進度、警告和診斷消息。示例如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -q -r Downloads root@linuxtechi:/var/tmp</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><h3 id="示例-12-在傳輸時使用-scp-中的識別文件-i" tabindex="-1">示例：12）在傳輸時使用 scp 中的識別文件（-i） <a class="header-anchor" href="#示例-12-在傳輸時使用-scp-中的識別文件-i" aria-label="Permalink to “示例：12）在傳輸時使用 scp 中的識別文件（-i）”">​</a></h3><p>在大多數 Linux 環境中，首選基於密鑰的身份驗證。在 <code>scp</code> 命令中，我們使用 <code>-i</code> 選項指定識別文件（私鑰文件），示例如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -i my_key.pem -r Downloads root@linuxtechi:/root</span></span></code></pre></div><p>在上面的示例中，<code>my_key.pem</code> 是識別文件或私鑰文件。</p><h3 id="示例-13-在-scp-中使用其他-ssh-config-文件-f" tabindex="-1">示例：13）在 scp 中使用其他 ssh_config 文件（-F） <a class="header-anchor" href="#示例-13-在-scp-中使用其他-ssh-config-文件-f" aria-label="Permalink to “示例：13）在 scp 中使用其他 ssh_config 文件（-F）”">​</a></h3><p>在某些情況下，你使用不同的網絡連接到 Linux 系統，可能某些網絡位於代理服務器後面，因此在這種情況下，我們必須具有不同的 <code>ssh_config</code> 文件。</p><p>通過 <code>-F</code> 選項在 <code>scp</code> 命令中指定了不同的 <code>ssh_config</code> 文件，示例如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -F /home/pkumar/new_ssh_config -r Downloads root@linuxtechi:/root</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>jdk-linux-x64_bin.rpm                     100%   10MB  16.6MB/s   00:00</span></span>
<span class="line"><span>backup-Oct.zip                            100%  713MB  41.9MB/s   00:17</span></span>
<span class="line"><span>index.html                                100%   85KB   6.6MB/s   00:00</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><h3 id="示例-14-在-scp-命令中使用其他加密方式-c" tabindex="-1">示例：14）在 scp 命令中使用其他加密方式（-c） <a class="header-anchor" href="#示例-14-在-scp-命令中使用其他加密方式-c" aria-label="Permalink to “示例：14）在 scp 命令中使用其他加密方式（-c）”">​</a></h3><p>默認情況下，<code>scp</code> 使用 AES-128 加密方式來加密文件。如果你想在 <code>scp</code> 命令中使用其他加密方式，請使用 <code>-c</code> 選項，後接加密方式名稱。</p><p>假設我們要在用 <code>scp</code> 命令傳輸文件時使用 3des-cbc 加密方式，請運行以下 <code>scp</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# scp -c 3des-cbc -r Downloads root@linuxtechi:/root</span></span></code></pre></div><p>使用以下命令列出 <code>ssh</code> 和 <code>scp</code> 支持的加密方式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ssh -Q cipher localhost | paste -d , -s -</span></span>
<span class="line"><span>3des-cbc,aes128-cbc,aes192-cbc,aes256-cbc,root@linuxtechi,aes128-ctr,aes192-ctr,aes256-ctr,root@linuxtechi,root@linuxtechi,root@linuxtechi</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>以上就是本教程的全部內容，要獲取有關 <code>scp</code> 命令的更多詳細信息，請參考其手冊頁。請在下面的評論部分中分享你的反饋和評論。</p><hr>`,69)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/scp-command-examples-in-linux/"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/scp-command-examples-in-linux/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...s[2]||(s[2]=[a("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const y=t(h,[["render",r]]);export{C as __pageData,y as default};
